def solve(payload):
    import re
    from collections import Counter
    counts = Counter()
    values = {}
    for name, value in payload["headers"]:
        name = name.strip().lower()
        counts[name] += 1
        values[name] = value.strip().lower()
    required = {"x-content-type-options", "x-frame-options", "referrer-policy"}
    issues = set()
    if values.get("x-content-type-options") != "nosniff":
        issues.add("content_type")
    if values.get("x-frame-options") not in {"deny", "sameorigin"}:
        issues.add("framing")
    if values.get("referrer-policy") not in {"no-referrer", "same-origin", "strict-origin-when-cross-origin"}:
        issues.add("referrer")
    if payload["https"]:
        required.add("strict-transport-security")
        directives = [part.strip() for part in values.get("strict-transport-security", "").split(";")]
        ages = [int(match.group(1)) for part in directives if (match := re.fullmatch(r"max-age=([0-9]+)", part))]
        age_directives = [part for part in directives if part.split("=", 1)[0].strip() == "max-age"]
        if len(ages) != 1 or len(age_directives) != 1 or ages[0] < 15552000 or "includesubdomains" not in directives:
            issues.add("hsts")
    for name in required:
        if counts[name] > 1:
            issues.add("duplicate:" + name)
    return {"issues": sorted(issues)}

